#!/usr/bin/env bash
# Max Player v81 update script
# Run from the repo root: ~/IdeaProjects/maxplayer
set -euo pipefail

if [ ! -f "pubspec.yaml" ]; then
  echo "ERROR: run this from the maxplayer repo root (pubspec.yaml not found here)."
  exit 1
fi

echo "==> Patching lib/state/media_player_state.dart (Ask-AI transcript race fix)"
python3 - <<'PYEOF'
import sys
p = "lib/state/media_player_state.dart"
s = open(p, encoding="utf-8").read()

def apply(old, new):
    global s
    if old not in s:
        sys.exit(f"[media_player_state.dart] anchor not found, aborting:\n{old[:150]}")
    s = s.replace(old, new, 1)

apply(
'''    // v77: these three used to be awaited here too, serially, before this
    // function returned - stacking a disk scan (subtitle attach) and an
    // mpv audio filter-graph rebuild right on top of the file just
    // opening was the real cause of "new video lags for a second". None
    // of them need to finish before the user can start watching, so they
    // now run in the background instead of blocking playback start.
    unawaited(() async {
      await _applyAudioFilters(); // equalizer + leveling survive file changes
      await _attachSidecarSubtitles(track.path);
      await _recordOpen(track);
    }());''',
'''    // v77: these three used to be awaited here too, serially, before this
    // function returned - stacking a disk scan (subtitle attach) and an
    // mpv audio filter-graph rebuild right on top of the file just
    // opening was the real cause of "new video lags for a second". None
    // of them need to finish before the user can start watching, so they
    // now run in the background instead of blocking playback start.
    // v81: kept as an awaitable future (not just fire-and-forget) so code
    // that genuinely needs this finished - like Ask-AI checking whether a
    // sidecar subtitle transcript exists - can await it instead of racing
    // it. Racing it was why "Ask AI about this video" could wrongly say
    // there's no transcript for a video that has a sidecar .srt, if asked
    // quickly after opening the video.
    _postOpenWork = () async {
      await _applyAudioFilters(); // equalizer + leveling survive file changes
      await _attachSidecarSubtitles(track.path);
      await _recordOpen(track);
    }();
    unawaited(_postOpenWork);''')

apply(
'''  /// file is a stream). Feeds the karaoke word-highlight overlay.
  List<SrtCue>? aiCues;
''',
'''  /// file is a stream). Feeds the karaoke word-highlight overlay.
  List<SrtCue>? aiCues;

  /// v81: the deferred post-open background work started in [_loadCurrent]
  /// (audio filters, sidecar subtitle attach, history write). Await this
  /// when you need one of those to have definitely finished - e.g. before
  /// checking [transcriptCues] for a just-opened video.
  Future<void>? _postOpenWork;
''')

apply(
'''  /// "Ask anything about this video" chat.
  List<SrtCue>? get transcriptCues => aiCues ?? sidecarCues;
''',
'''  /// "Ask anything about this video" chat.
  List<SrtCue>? get transcriptCues => aiCues ?? sidecarCues;

  /// v81: same as [transcriptCues], but waits for the just-opened video's
  /// deferred sidecar-subtitle attach to finish first (see [_postOpenWork]
  /// in [_loadCurrent]). Use this instead of the plain getter anywhere the
  /// answer needs to be accurate right after opening a video - the plain
  /// getter can read null too early and wrongly report "no transcript".
  Future<List<SrtCue>?> awaitTranscriptCues() async {
    await _postOpenWork;
    return transcriptCues;
  }
''')

open(p, "w", encoding="utf-8").write(s)
print("  OK")
PYEOF

echo "==> Patching lib/screens/player_screen.dart (use the race-safe transcript getter)"
python3 - <<'PYEOF'
import sys
p = "lib/screens/player_screen.dart"
s = open(p, encoding="utf-8").read()
old = '''  Future<void> _openVideoAsk() async {
    final track = widget.player.currentTrack;
    if (track == null) return;
    final cues = widget.player.transcriptCues;
    await VideoAskSheet.show(
      context,
      title: track.title,
      cues: cues ?? const [],
      onSeek: (at) => widget.player.seek(at),
    );
  }'''
new = '''  Future<void> _openVideoAsk() async {
    final track = widget.player.currentTrack;
    if (track == null) return;
    final cues = await widget.player.awaitTranscriptCues();
    if (!mounted) return;
    await VideoAskSheet.show(
      context,
      title: track.title,
      cues: cues ?? const [],
      onSeek: (at) => widget.player.seek(at),
    );
  }'''
if old not in s:
    sys.exit("[player_screen.dart] anchor not found, aborting")
s = s.replace(old, new, 1)
open(p, "w", encoding="utf-8").write(s)
print("  OK")
PYEOF

echo "==> Patching lib/widgets/video_ask_sheet.dart (fix AI answers silently not saving after restart)"
python3 - <<'PYEOF'
import sys
p = "lib/widgets/video_ask_sheet.dart"
s = open(p, encoding="utf-8").read()
old = '''    _loadFromDisk().then((_) {
      if (!mounted) return;
      final cached = _sessionCache[widget.title];
      if (cached != null && cached.isNotEmpty && _messages.isEmpty) {
        setState(() {
          _messages
            ..clear()
            ..addAll(cached);
        });
        _scrollToBottom();
      }
    });'''
new = '''    _loadFromDisk().then((_) {
      if (!mounted) return;
      final cached = _sessionCache[widget.title];
      if (cached != null && cached.isNotEmpty && _messages.isEmpty) {
        setState(() {
          _messages.addAll(cached);
          // v81: keep _sessionCache pointing at the SAME list _messages
          // uses from now on - otherwise every future _messages.add() in
          // _ask() silently stops reaching _sessionCache (and therefore
          // _persistToDisk()), because they'd be two different list
          // objects holding the same values only at this one moment. This
          // was why AI answers stopped saving after the very first
          // reopen following a restart.
          _sessionCache[widget.title] = _messages;
        });
        _scrollToBottom();
      }
    });'''
if old not in s:
    sys.exit("[video_ask_sheet.dart] anchor not found, aborting")
s = s.replace(old, new, 1)
open(p, "w", encoding="utf-8").write(s)
print("  OK")
PYEOF

echo "==> Patching lib/widgets/ai_suggest_sheet.dart (persist AI Suggestor results to disk)"
python3 - <<'PYEOF'
import sys
p = "lib/widgets/ai_suggest_sheet.dart"
s = open(p, encoding="utf-8").read()

def apply(old, new):
    global s
    if old not in s:
        sys.exit(f"[ai_suggest_sheet.dart] anchor not found, aborting:\n{old[:150]}")
    s = s.replace(old, new, 1)

apply(
'''import 'package:flutter/material.dart';

import '../services/ai_suggest.dart';
import '../services/tmdb_client.dart';
import '../state/theme_state.dart';
import 'tmdb_image.dart';''',
'''import 'dart:async';
import 'dart:convert';

import 'package:flutter/material.dart';

import '../services/ai_suggest.dart';
import '../services/native_bridge.dart';
import '../services/tmdb_client.dart';
import '../state/theme_state.dart';
import 'tmdb_image.dart';''')

apply(
'''  /// v77: in-memory cache of the last taste query + picks, so closing
  /// this sheet (a dismissible bottom sheet - Flutter tears its whole
  /// State down on close) and reopening it shows what the AI already
  /// generated instead of a blank sheet. Overwritten the moment a new
  /// query is submitted.
  static String? _lastQuery;
  static List<TmdbMovie> _lastPicks = const [];

  @override
  void initState() {
    super.initState();
    if (_lastQuery != null) {
      _tasteCtrl.text = _lastQuery!;
      _picks = _lastPicks;
    }
  }''',
'''  /// v77: in-memory cache of the last taste query + picks, so closing
  /// this sheet (a dismissible bottom sheet - Flutter tears its whole
  /// State down on close) and reopening it shows what the AI already
  /// generated instead of a blank sheet. Overwritten the moment a new
  /// query is submitted.
  /// v81: now also backed by disk (SharedPreferences via NativeBridge),
  /// so it survives restarting the app too.
  static String? _lastQuery;
  static List<TmdbMovie> _lastPicks = const [];
  static bool _diskLoaded = false;
  static const String _kPrefKey = 'ai.suggestorCache';

  static TmdbMovie _movieFromJson(Map<String, dynamic> m) => TmdbMovie(
        id: m['id'] as int,
        title: m['title'] as String,
        rating: (m['rating'] as num).toDouble(),
        year: m['year'] as int?,
        posterPath: m['posterPath'] as String?,
        backdropPath: m['backdropPath'] as String?,
        overview: m['overview'] as String? ?? '',
        kind: m['kind'] as String? ?? 'movie',
      );

  static Map<String, dynamic> _movieToJson(TmdbMovie m) => {
        'id': m.id,
        'title': m.title,
        'rating': m.rating,
        'year': m.year,
        'posterPath': m.posterPath,
        'backdropPath': m.backdropPath,
        'overview': m.overview,
        'kind': m.kind,
      };

  static Future<void> _loadFromDisk() async {
    if (_diskLoaded) return;
    _diskLoaded = true;
    try {
      final raw = (await NativeBridge.loadSettings())[_kPrefKey];
      if (raw == null || raw.isEmpty) return;
      final decoded = jsonDecode(raw) as Map<String, dynamic>;
      _lastQuery = decoded['query'] as String?;
      _lastPicks = [
        for (final m in (decoded['picks'] as List))
          _movieFromJson(m as Map<String, dynamic>),
      ];
    } catch (_) {
      // Corrupt/old cache - ignore, just start fresh.
    }
  }

  static void _persistToDisk() {
    final encoded = jsonEncode({
      'query': _lastQuery,
      'picks': [for (final m in _lastPicks) _movieToJson(m)],
    });
    unawaited(NativeBridge.saveSetting(_kPrefKey, encoded));
  }

  @override
  void initState() {
    super.initState();
    if (_lastQuery != null) {
      _tasteCtrl.text = _lastQuery!;
      _picks = _lastPicks;
    }
    _loadFromDisk().then((_) {
      if (!mounted || _picks.isNotEmpty) return;
      if (_lastQuery != null) {
        setState(() {
          _tasteCtrl.text = _lastQuery!;
          _picks = _lastPicks;
        });
      }
    });
  }''')

apply(
'''      } else {
        _picks = picks;
        _lastQuery = q;
        _lastPicks = picks;
      }''',
'''      } else {
        _picks = picks;
        _lastQuery = q;
        _lastPicks = picks;
        _persistToDisk();
      }''')

open(p, "w", encoding="utf-8").write(s)
print("  OK")
PYEOF
