echo "  wrote android/app/src/main/res/drawable/splash_logo.png"

echo ""
echo "===================================================================="
echo " v81 applied. What changed:"
echo "  1. Fixed 'Ask AI about this video' not working on videos that"
echo "     already have subtitles - a real regression from my own v76/v77"
echo "     startup-lag fix. Sidecar-subtitle attaching was moved to run in"
echo "     the background so playback starts faster, but 'Ask AI' could"
echo "     fire before that background work finished and wrongly report"
echo "     'no transcript'. It now waits for that work to finish first."
echo "  2. Fixed AI answers (video Ask-AI) silently not saving after the"
echo "     first reopen following a restart - restoring from disk was"
echo "     pointing _messages and the save-cache at two different list"
echo "     objects, so new answers stopped reaching the part that saves"
echo "     to disk. Same root shape of bug fixed for the AI Suggestor too."
echo "  3. AI Suggestor results now persist across app restarts (were only"
echo "     ever kept in memory before, lost on every restart)"
echo "  4. App icon: brought back a small margin (v79 went too far the"
echo "     other way to full-bleed, which the adaptive mask crops into,"
echo "     making it look zoomed) - background is still kept as you asked"
echo "===================================================================="
echo ""
echo "On 'Ask AI about this video' still not working for embedded subtitles:"
echo "  If your video's subtitles are baked INTO the file (an MKV's own"
echo "  subtitle track you turn on via the Subtitles button) rather than a"
echo "  separate .srt file next to it, this fix does NOT cover that case -"
echo "  those are rendered internally by the video engine and were never"
echo "  exposed as readable text to the app. Making that work needs"
echo "  extracting the subtitle stream to a real file first (would need a"
echo "  proper ffmpeg command-runner dependency and real device testing -"
echo "  I don't want to ship that blind after the v75 lesson). If that's"
echo "  what you meant, confirm and I'll scope it properly next round."
echo "===================================================================="
echo ""
echo "Next steps:"
echo "  flutter analyze        # should print: No issues found!"
echo "  flutter test"
echo "  flutter build appbundle --release"
echo "  git add -A && git commit -m 'v81: fix Ask-AI transcript race, fix AI answers not saving after restart, persist AI Suggestor, fix icon zoom' && git push"
